import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

function App() {

  const [model, setModel] = React.useState(appsmith.model);
  const [selected, setSelected] = React.useState(null);
  const [ascending, setAscending] = React.useState(true);

  const prevHeaderRef = React.useRef(model.header || "Location");

  React.useEffect(() => {
    const unsub = appsmith.onModelChange((newModel) => {
      setModel({...newModel});
      const newHeader = newModel.header || "Location";
      if (prevHeaderRef.current !== newHeader) {
        setSelected(null);
        prevHeaderRef.current = newHeader;
      }
    });
    return () => { if (unsub) unsub(); };
  }, []);

  const options = model.data || [];
  const header = model.header || "Location";

  const sortedOptions = React.useMemo(() => {

    return [...options].sort((a,b)=>{

      if(ascending)
        return a.label.localeCompare(b.label);

      return b.label.localeCompare(a.label);

    });

  },[options,ascending]);


  const toggleValue = (value) => {

    let newValue = selected === value ? null : value;

    setSelected(newValue);

    appsmith.updateModel({
      selectedValue: newValue
    });

    appsmith.triggerEvent("onSelectChange");
  };


  const toggleSort = () => {
    setAscending(!ascending);
  };


  return (
    <div className="app">

      <div className="header">

        <div>{header}</div>

        <div
          className="sortIcon"
          onClick={toggleSort}
        >
          {ascending ? "\u25B2" : "\u25BC"}
        </div>

      </div>

      <div className="list">

        {sortedOptions.map((opt,i)=>(

          <div
            key={i}
            className={
              "row " +
              (selected===opt.value ? "selected":"")
            }
            onClick={()=>toggleValue(opt.value)}
          >
            <span className="tooltip">{opt.label}</span>
            {opt.label}

          </div>

        ))}

      </div>

    </div>
  );
}

appsmith.onReady(()=>{

 ReactDOM.render(
   <App />,
   document.getElementById("root")
 );

});
